import type { ReactNode } from "react";

// 수치(단위가 붙은 숫자, "A → B" 비교 포함)를 굵게 표시해 훑어볼 때 먼저 보이게 한다.
const metricPattern =
  /(\d[\d,.]*(?:~\d[\d,.]*)?(?:만|천)?\s?(?:MB|KB|일|시간|점|개|건|%|분|종|명)(?:\s?→\s?\d[\d,.]*(?:~\d[\d,.]*)?\s?(?:MB|KB|일|시간|점|개|건|%|분|종|명))?)/;

export function emphasize(text: string): ReactNode[] {
  return text.split(metricPattern).map((part, index) => (index % 2 === 1 ? <b key={index}>{part}</b> : part));
}
